 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [[0] * 7 for _ in range(h)]
    # Transfer the red locator into the output canvas.
    for r in range(h):
        for c in range(8, w):
            if grid[r][c] == 5:
                out[r][c - 8] = 5

    # Recognize the small source glyphs.  Their output tokens are straight
    # strokes: S -> 3 horizontal, P -> 2 horizontal, Q -> 2 vertical,
    # R -> 4 horizontal.
    types = {
        ((1,1,0),(1,0,1),(0,1,0)): ('h', 3),
        ((1,0,1),(1,0,1),(1,1,1)): ('h', 2),
        ((1,0,1),(0,1,0),(0,1,0)): ('v', 2),
        ((1,1,1),(0,1,0),(1,0,1)): ('h', 4),
    }
    motifs = []
    r = 0
    while r < h:
        if not any(grid[r][c] for c in range(7)):
            r += 1
            continue
        top = r
        while r < h and any(grid[r][c] for c in range(7)):
            r += 1
        for left in (0, 4):
            cells = [[grid[rr][left + cc] for cc in range(3)] for rr in range(top, r)]
            if len(cells) != 3:
                continue
            color = next((v for row in cells for v in row if v), 0)
            shape = tuple(tuple(int(v != 0) for v in row) for row in cells)
            if shape in types and color:
                orient, length = types[shape]
                motifs.append((color, orient, length))

    # The output is a compact stream of these strokes.  Consecutive vertical
    # tokens occupy two rows; horizontal tokens occupy one row.
    row = 1
    for color, orient, length in motifs:
        if row >= h:
            break
        if orient == 'h':
            start = 1 if length == 4 else 2
            for c in range(start, min(start + length, 7)):
                out[row][c] = color
            row += 1
        else:
            col = 4 if color == 6 else 2
            for rr in range(row, min(row + length, h)):
                out[rr][col] = color
            row += length
    return out
