            elif shape == ((1,0,1),(1,0,1),(1,1,1)):
                motifs.append((color, 'B'))
            elif shape == ((1,0,1),(0,1,0),(0,1,0)):
                motifs.append((color, 'C'))
            elif shape == ((1,1,1),(0,1,0),(1,0,1)):
                motifs.append((color, 'D'))
