        ((1, 0, 1), (0, 1, 0), (0, 1, 0)): 'C',  # down, length 2
        ((1, 1, 1), (0, 1, 0), (1, 0, 1)): 'D',  # left, length 4
    }
    tops = []
    r = 0
    while r < h:
        if not any(grid[r][c] for c in range(7)):
