    while r<h:
        if not any(grid[r][c] for c in range(7)):
            r+=1; continue
        top=r
        while r<h and any(grid[r][c] for c in range(7)): r+=1
        if r-top>=3: bands.append(top)
    for top in bands:
        for left in (0,4):
            mat=[[grid[top+i][left+j] for j in range(3)] for i in range(3)]
            cells=[(i,j,mat[i][j]) for i in range(3) for j in range(3) if mat[i][j]]
            if not cells: continue
            color=cells[0][2]
