    h, w = len(grid), len(grid[0])
    out = [[0] * 7 for _ in range(h)]
    # 5 is the locator; erase divider and retain locator on a 7-wide panel.
    for r in range(h):
        for c in range(8, w):
            if grid[r][c] == 5:
                out[r][c - 8] = 5

    # Detect bands and identify the two glyphs within each. The reduced form
    # is drawn beside the locator, with the left and right glyphs sharing the
    # same output row but occupying adjacent line positions.
    bands=[]
    r=0
    while r<h:
        if not any(grid[r][c] for c in range(7)):
            r+=1
            continue
        top=r
        while r<h and any(grid[r][c] for c in range(7)):
            r+=1
        if r-top>=3: bands.append(top)
    for top in bands:
        for left in (0,4):
            block=[[grid[top+i][left+j] for j in range(3)] for i in range(3)]
            pts=[(i,j,block[i][j]) for i in range(3) for j in range(3) if block[i][j]]
            if not pts: continue
            color=pts[0][2]
            n=len(pts)
            if n==5:
                start=1 if left==0 else 3
                for c in range(start,start+3): out[top][c]=color
            elif n==7:
                start=2 if left==0 else 4
                for c in range(start,start+2): out[top][c]=color
            elif n==4:
                col=1 if left==0 else 5
                for rr in range(top,min(top+2,h)): out[rr][col]=color
            elif n==6:
                start=1 if left==0 else 2
                for c in range(start,start+4):
                    if c<7: out[top][c]=color
    return out
