    h, w = len(grid), len(grid[0])
    out = [[0] * 7 for _ in range(h)]

    marker = None
    for r, row in enumerate(grid):
        for c in range(8, w):
            if row[c] == 5:
                marker = (r, c - 8)
                out[r][c - 8] = 5
                break
        if marker is not None:
            break
    if marker is None:
        return out

    # Glyphs denote path segments: A=right 3, B=left 2,
    # C=down 2, D=left 4.
    glyphs = {
        ((1, 1, 0), (1, 0, 1), (0, 1, 0)): ('R', 3),
        ((1, 0, 1), (1, 0, 1), (1, 1, 1)): ('L', 2),
        ((1, 0, 1), (0, 1, 0), (0, 1, 0)): ('D', 2),
        ((1, 1, 1), (0, 1, 0), (1, 0, 1)): ('L', 4),
    }

    bands = []
    r = 0
    while r < h:
        if not any(grid[r][c] for c in range(7)):
            r += 1
            continue
        top = r
        while r < h and any(grid[r][c] for c in range(7)):
            r += 1
        if r - top >= 3:
            bands.append(top)

    # Route order: down the left motif column, then down the right.
    segments = []
    for left in (0, 4):
        for top in bands:
            mask = tuple(tuple(int(grid[top+i][left+j] != 0) for j in range(3))
                         for i in range(3))
            color = next((grid[top+i][left+j] for i in range(3) for j in range(3)
                          if grid[top+i][left+j]), 0)
            if color and mask in glyphs:
                direction, length = glyphs[mask]
                segments.append((direction, length, color))

    row, col = marker
    for direction, length, color in segments:
        if direction == 'D':
            for k in range(1, length + 1):
                if row + k < h:
                    out[row + k][col] = color
            row += length
        else:
            row += 1
            if row >= h:
