    for r, row in enumerate(grid):
        for c in range(8, len(row)):
            if row[c] == 5:
                out[r][c - 8] = 5

    # Decode each adjacent 3x3 motif bank into its demonstrated stroke layout.
    r = 0
    while r < h:
        if not any(grid[r][c] for c in range(7)):
            r += 1
            continue
        top = r
        while r < h and any(grid[r][c] for c in range(7)):
            r += 1
        if r - top < 3:
            continue
        for left in (0, 4):
            block = [[grid[top + i][left + j] for j in range(3)] for i in range(3)]
            color = next((v for row in block for v in row if v), 0)
            mask = tuple(tuple(int(v != 0) for v in row) for row in block)
            if not color:
                continue
            if mask == ((1, 1, 0), (1, 0, 1), (0, 1, 0)):
                # Three-cell bar, with placement based on source bank.
                start = 2 if left == 0 else 3
                for c in range(start, start + 3):
                    out[top][c] = color
            elif mask == ((1, 0, 1), (1, 0, 1), (1, 1, 1)):
                # Two-cell bar.
                start = 2 if left == 0 else 4
                for c in range(start, start + 2):
                    out[top][c] = color
            elif mask == ((1, 0, 1), (0, 1, 0), (0, 1, 0)):
                # Two-cell vertical stroke.
                col = 1 if left == 0 else 5
                out[top][col] = color
                if top + 1 < h:
                    out[top + 1][col] = color
            elif mask == ((1, 1, 1), (0, 1, 0), (1, 0, 1)):
                # Four-cell bar.
